#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (__int128)res * base % MOD;
        base = (__int128)base * base % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

struct Line {
    long long m, c;
};

// Returns true if line l2 is redundant given l1 and l3 (m1 < m2 < m3)
bool isRedundant(const Line& l1, const Line& l2, const Line& l3) {
    return (__int128)(l1.c - l2.c) * (l3.m - l1.m) >= (__int128)(l1.c - l3.c) * (l2.m - l1.m);
}

struct Meal {
    long long a, b;
};

bool compareMeals(const Meal& m1, const Meal& m2) {
    // m1 comes before m2 if b1 * (a2 - 1) > b2 * (a1 - 1)
    __int128 v1 = (__int128)m1.b * (m2.a - 1);
    __int128 v2 = (__int128)m2.b * (m1.a - 1);
    return v1 > v2;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    long long K;
    if (!(cin >> N >> M >> K)) return 0;

    vector<long long> a(N), b(N);
    for (int i = 0; i < N; ++i) cin >> a[i];
    for (int i = 0; i < N; ++i) cin >> b[i];

    vector<Meal> meals(M);
    for (int i = 0; i < M; ++i) cin >> meals[i].a;
    for (int i = 0; i < M; ++i) cin >> meals[i].b;

    int Q;
    cin >> Q;
    vector<long long> queries(Q);
    for (int i = 0; i < Q; ++i) cin >> queries[i];

    // 1. Process Meals
    sort(meals.begin(), meals.end(), compareMeals);
    long long A_meal = 1, B_meal = 0;
    for (int i = 0; i < M; ++i) {
        long long ma = meals[i].a % MOD;
        long long mb = meals[i].b % MOD;
        A_meal = (__int128)A_meal * ma % MOD;
        B_meal = ((__int128)B_meal * ma + mb) % MOD;
    }

    // 2. Process Spells
    long long max_a = 0;
    long long max_b_for_max_a = -1;
    for (int i = 0; i < N; ++i) {
        if (a[i] > max_a) {
            max_a = a[i];
            max_b_for_max_a = b[i];
        } else if (a[i] == max_a) {
            max_b_for_max_a = max(max_b_for_max_a, b[i]);
        }
    }

    if (max_a == 1) {
        // All spells have a_i = 1.
        long long max_b = 0;
        for (int i = 0; i < N; ++i) {
            max_b = max(max_b, b[i]);
        }

        long long add = (K % MOD) * (max_b % MOD) % MOD;
        for (int q = 0; q < Q; ++q) {
            long long x = queries[q];
            long long y = (x % MOD + add) % MOD;
            long long ans = ((__int128)A_meal * y + B_meal) % MOD;
            cout << ans << "\n";
        }
        return 0;
    }

    // max_a >= 2
    // Build Upper Convex Hull of lines y = a_i * x + b_i
    vector<Line> lines(N);
    for (int i = 0; i < N; ++i) {
        lines[i] = {a[i], b[i]};
    }
    sort(lines.begin(), lines.end(), [](const Line& l1, const Line& l2) {
        if (l1.m != l2.m) return l1.m < l2.m;
        return l1.c < l2.c;
    });

    vector<Line> filtered;
    for (int i = 0; i < N; ++i) {
        if (!filtered.empty() && filtered.back().m == lines[i].m) {
            filtered.pop_back();
        }
        filtered.push_back(lines[i]);
    }

    vector<Line> hull;
    for (const auto& l : filtered) {
        while (hull.size() >= 2 && isRedundant(hull[hull.size() - 2], hull.back(), l)) {
            hull.pop_back();
        }
        hull.push_back(l);
    }

    // Precompute constants for applying F, (K - 1) times:
    // F(v) = A * v + B_F
    // F^(K-1)(v) = A^(K-1) * v + B_F * (A^(K-1) - 1) / (A - 1)
    long long A = max_a;
    long long B_F = max_b_for_max_a;

    long long A_pow = power(A, K - 1);
    long long geom_sum;
    if ((A - 1) % MOD == 0) {
        geom_sum = (K - 1) % MOD;
    } else {
        long long num = (A_pow - 1 + MOD) % MOD;
        long long den = modInverse((A - 1) % MOD);
        geom_sum = (__int128)num * den % MOD;
    }
    long long F_add = (__int128)(B_F % MOD) * geom_sum % MOD;

    // Answer queries
    for (int q = 0; q < Q; ++q) {
        long long x = queries[q];

        // Binary search on hull for best line at x
        int low = 0, high = (int)hull.size() - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            // Compare hull[mid] and hull[mid + 1] at x
            // hull[mid].m * x + hull[mid].c <= hull[mid+1].m * x + hull[mid+1].c
            __int128 val1 = (__int128)hull[mid].m * x + hull[mid].c;
            __int128 val2 = (__int128)hull[mid + 1].m * x + hull[mid + 1].c;
            if (val1 <= val2) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        long long best_m = hull[low].m % MOD;
        long long best_c = hull[low].c % MOD;
        long long v = ((__int128)best_m * (x % MOD) + best_c) % MOD;

        long long y = ((__int128)A_pow * v + F_add) % MOD;
        long long ans = ((__int128)A_meal * y + B_meal) % MOD;

        cout << ans << "\n";
    }

    return 0;
}
